            node.put("background_class",view.getBackground()==null?"none":view.getBackground().getClass().getSimpleName()).put("elevation",view.getElevation());if(android.os.Build.VERSION.SDK_INT>=28)node.put("shadow_color",view.getOutlineAmbientShadowColor());if(view instanceof TextView text)node.put("text_sp",text.getTextSize()/text.getResources().getDisplayMetrics().scaledDensity).put("text_color",text.getCurrentTextColor());
